create table if not exists public.zz_town_test(i serial, k text, v text);
do $t$ declare c json; rid bigint; tid text; m int; cu text; mg int; begin
c := public.town_create('ZZ測試鎮','甲','1234','{}'::jsonb); rid := (c->>'resident_id')::bigint; tid := c->>'town_id';
select money into m from public.town_residents where id=rid; select currency into cu from public.town_towns where id=tid; insert into public.zz_town_test(k,v) values ('start',m||' '||cu);
begin update public.town_residents set place='office',energy=90,items=items||jsonb_build_object('rent',to_char(now() at time zone 'Asia/Taipei','YYYY-MM-DD')) where id=rid; select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('work_before',m::text); perform public.town_act(rid,'1234','work'); exception when others then insert into public.zz_town_test(k,v) values ('work_ERR',sqlerrm); end;
select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('work_after',m::text||' hl='||coalesce((select items->>'hl' from public.town_residents where id=rid),'-')||' wishm='||coalesce((select items->'wish'->>'m' from public.town_residents where id=rid),'-'));
begin update public.town_residents set place='home:'||rid,hunger=10 where id=rid; select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('eat_home_before',m::text); perform public.town_act(rid,'1234','eat'); exception when others then insert into public.zz_town_test(k,v) values ('eat_home_ERR',sqlerrm); end;
select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('eat_home_after',m::text||' hl='||coalesce((select items->>'hl' from public.town_residents where id=rid),'-')||' wishm='||coalesce((select items->'wish'->>'m' from public.town_residents where id=rid),'-'));
begin update public.town_residents set place='restaurant' where id=rid; select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('dine_before',m::text); perform public.town_act(rid,'1234','dine'); exception when others then insert into public.zz_town_test(k,v) values ('dine_ERR',sqlerrm); end;
select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('dine_after',m::text||' hl='||coalesce((select items->>'hl' from public.town_residents where id=rid),'-')||' wishm='||coalesce((select items->'wish'->>'m' from public.town_residents where id=rid),'-'));
begin update public.town_residents set place='cafe' where id=rid; select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('coffee_before',m::text); perform public.town_act(rid,'1234','coffee'); exception when others then insert into public.zz_town_test(k,v) values ('coffee_ERR',sqlerrm); end;
select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('coffee_after',m::text||' hl='||coalesce((select items->>'hl' from public.town_residents where id=rid),'-')||' wishm='||coalesce((select items->'wish'->>'m' from public.town_residents where id=rid),'-'));
begin update public.town_residents set place='cinema' where id=rid; select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('movie_before',m::text); perform public.town_act(rid,'1234','movie'); exception when others then insert into public.zz_town_test(k,v) values ('movie_ERR',sqlerrm); end;
select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('movie_after',m::text||' hl='||coalesce((select items->>'hl' from public.town_residents where id=rid),'-')||' wishm='||coalesce((select items->'wish'->>'m' from public.town_residents where id=rid),'-'));
begin update public.town_residents set place='market' where id=rid; select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('buy_gift_before',m::text); perform public.town_act(rid,'1234','buy',null,null,null,null,'gift'); exception when others then insert into public.zz_town_test(k,v) values ('buy_gift_ERR',sqlerrm); end;
select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('buy_gift_after',m::text||' hl='||coalesce((select items->>'hl' from public.town_residents where id=rid),'-')||' wishm='||coalesce((select items->'wish'->>'m' from public.town_residents where id=rid),'-'));
begin  select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('buy_bed_before',m::text); perform public.town_act(rid,'1234','buy',null,null,null,null,'f:rug'); exception when others then insert into public.zz_town_test(k,v) values ('buy_bed_ERR',sqlerrm); end;
select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('buy_bed_after',m::text||' hl='||coalesce((select items->>'hl' from public.town_residents where id=rid),'-')||' wishm='||coalesce((select items->'wish'->>'m' from public.town_residents where id=rid),'-'));
begin update public.town_residents set place='home:'||rid where id=rid; select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('upgrade_noMoney_before',m::text); perform public.town_act(rid,'1234','upgrade'); exception when others then insert into public.zz_town_test(k,v) values ('upgrade_noMoney_ERR',sqlerrm); end;
select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('upgrade_noMoney_after',m::text||' hl='||coalesce((select items->>'hl' from public.town_residents where id=rid),'-')||' wishm='||coalesce((select items->'wish'->>'m' from public.town_residents where id=rid),'-'));
begin update public.town_residents set place='plaza',money=5000 where id=rid; select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('rps_bet20_before',m::text); perform public.town_game(rid,'1234','rps',20,'r'); exception when others then insert into public.zz_town_test(k,v) values ('rps_bet20_ERR',sqlerrm); end;
select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('rps_bet20_after',m::text||' hl='||coalesce((select items->>'hl' from public.town_residents where id=rid),'-')||' wishm='||coalesce((select items->'wish'->>'m' from public.town_residents where id=rid),'-'));
begin  select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('rps_bet50_before',m::text); perform public.town_game(rid,'1234','rps',50,'r'); exception when others then insert into public.zz_town_test(k,v) values ('rps_bet50_ERR',sqlerrm); end;
select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('rps_bet50_after',m::text||' hl='||coalesce((select items->>'hl' from public.town_residents where id=rid),'-')||' wishm='||coalesce((select items->'wish'->>'m' from public.town_residents where id=rid),'-'));
begin  select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('rps_bet1000_before',m::text); perform public.town_game(rid,'1234','rps',1000,'r'); exception when others then insert into public.zz_town_test(k,v) values ('rps_bet1000_ERR',sqlerrm); end;
select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('rps_bet1000_after',m::text||' hl='||coalesce((select items->>'hl' from public.town_residents where id=rid),'-')||' wishm='||coalesce((select items->'wish'->>'m' from public.town_residents where id=rid),'-'));
begin  select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('rps_bet1500_before',m::text); perform public.town_game(rid,'1234','rps',1500,'r'); exception when others then insert into public.zz_town_test(k,v) values ('rps_bet1500_ERR',sqlerrm); end;
select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('rps_bet1500_after',m::text||' hl='||coalesce((select items->>'hl' from public.town_residents where id=rid),'-')||' wishm='||coalesce((select items->'wish'->>'m' from public.town_residents where id=rid),'-'));
begin update public.town_residents set place='home:'||rid,money=10000 where id=rid; select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('upgrade10000_before',m::text); perform public.town_act(rid,'1234','upgrade'); exception when others then insert into public.zz_town_test(k,v) values ('upgrade10000_ERR',sqlerrm); end;
select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('upgrade10000_after',m::text||' hl='||coalesce((select items->>'hl' from public.town_residents where id=rid),'-')||' wishm='||coalesce((select items->'wish'->>'m' from public.town_residents where id=rid),'-'));
begin update public.town_residents set place='park',money=30000,items=items||'{"wish":{"k":"rich","m":0}}'::jsonb where id=rid; select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('wish_rich_before',m::text); perform public.town_act(rid,'1234','play'); exception when others then insert into public.zz_town_test(k,v) values ('wish_rich_ERR',sqlerrm); end;
select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('wish_rich_after',m::text||' hl='||coalesce((select items->>'hl' from public.town_residents where id=rid),'-')||' wishm='||coalesce((select items->'wish'->>'m' from public.town_residents where id=rid),'-'));
begin update public.town_residents set place='home:'||rid,money=5000,items=items||'{"rent":"2000-01-01"}'::jsonb where id=rid; select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('rent_before',m::text); perform public.town_act(rid,'1234','toilet'); exception when others then insert into public.zz_town_test(k,v) values ('rent_ERR',sqlerrm); end;
select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('rent_after',m::text||' hl='||coalesce((select items->>'hl' from public.town_residents where id=rid),'-')||' wishm='||coalesce((select items->'wish'->>'m' from public.town_residents where id=rid),'-'));
select count(*) into mg from public.town_migrations where id='price2025'; insert into public.zz_town_test(k,v) values ('mig_rows',mg::text);
update public.town_residents set money=1000 where id=rid;
if not exists (select 1 from public.town_migrations where id='price2025') then update public.town_residents set money=money*6 where id=rid; end if;
select money into m from public.town_residents where id=rid; insert into public.zz_town_test(k,v) values ('mig_rerun_money_should_be_1000',m::text);
delete from public.town_towns where id=tid; end $t$;